(6038552, 0, 'GOBIN!!!', '', 15, 0, 0, 0, 0, 0, 0, 0, 1, 15595),
(6050072, 0, 'Get in there and show those zombies what the Bilgewater Buccaneers are made of, kid!', '', 0, 0, 0, 0, 0, 0, 0, 0, 0, 15595),
(6050083, 0, 'You\'re going to love this!', '', 0, 0, 0, 0, 0, 0, 0, 0, 0, 15595),
(6050106, 0, 'We\'re gonna make you the ultimate footbomb uniform, kid. But first, we need parts. Lots of them.', '', 0, 0, 0, 0, 0, 0, 0, 0, 0, 15595),
(6038767, 0, 'Little help here!', 'Little help here!', 0, 0, 0, 0, 0, 0, 0, 0, 1, 15595),
(6037333, 0, 'How about this: Instant water! Just add... oh.', 'How about this: Instant water! Just add... oh.', 0, 0, 0, 0, 0, 0, 0, 0, 1, 15595),
(6037420, 0, 'Bagel-holes!', 'Bagel-holes!', 0, 0, 0, 0, 0, 0, 0, 0, 1, 15595),
