(6039496, 0, 'Um... you do realize there\'s a bottom to this cage?!', 'Um... you do realize there\'s a bottom to this cage?!', 0, 0, 0, 0, 0, 0, 0, 0, 1, 15595),
(6039500, 0, 'Just open the door... oh no!', 'Just open the door... oh no!', 0, 0, 0, 0, 0, 0, 0, 0, 1, 15595),
(6039574, 0, 'I\'m so money!', '', 0, 0, 0, 0, 0, 0, 0, 0, 1, 15595),
(6047396, 0, 'No one attacks the Big G and lives!', '', 0, 0, 0, 0, 0, 0, 0, 0, 1, 15595),
(6039572, 0, 'Here\'s some of that moolah back that I took from you!', '', 0, 0, 0, 0, 0, 0, 0, 0, 1, 15595),
(6039530, 0, 'I SEE THE TRAITOR IS HERE TO RESCUE YOU, WARCHIEF. HOW CONVENIENT. YOU WILL BOTH BOW TO ME OR FALL TOGETHER!', '', 0, 0, 0, 0, 0, 0, 0, 0, 1, 15595),
